data.content:
/* part:page.style.kit.calendar */
/* Kit css: Calendar    kit version 1.0.0    pairs with kit/calendar.js
   .kit-cal (the root; a size container named kit-cal) > .kit-cal-tools (.kit-cal-nav with .kit-cal-btn buttons, h2.kit-cal-title, .kit-cal-views radios .kit-cal-vb)
   + .kit-cal-body + .kit-cal-pop (the dialog). Views: .kit-cal-month (grid of .kit-cal-strip rows: .kit-cal-cell days, .kit-cal-ev bars and chips, .kit-cal-more)
   with .kit-cal-under (the chosen day's list, shown under 480px); .kit-cal-tv (.kit-cal-scroll > .kit-cal-top [.kit-cal-dh day heads, .kit-cal-ad all-day row]
   + .kit-cal-tgw [.kit-cal-tg slots, .kit-cal-evl columns of .kit-cal-tev events and .kit-cal-now]); .kit-cal-agenda (.kit-cal-ag-day sections).
   States have a shape as well as a colour: today is a filled disc and the word Today; selected days and slots are outlined and hatched; disabled days are
   struck through and hatched; weekends are shaded; an event continuing past the row loses its rounded corner and shows a chevron. --ev is an event's colour.
   Needs from the board: --panel --sunk --bg --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --shadow --f-ui --f-mono
   and the pens --c-blue --c-red --c-green --c-amber --c-violet --c-ink; optional --focus, --radius (default 8px), --cal-hour (one hour of the time axis,
   default 3rem), --cal-height (the time view's scroll height, default 34rem). */
.kit-cal { --cal-num-h: 1.75rem; --cal-bar-h: 1.375rem; --cal-more-h: 1.25rem; --cal-axis: 3.75rem; --cal-r: var(--radius, 8px);
  container: kit-cal / inline-size; position: relative; min-width: 0; color: var(--ink); font: 14px/1.4 var(--f-ui); }
.kit-cal *, .kit-cal *::before, .kit-cal *::after { box-sizing: border-box; }
.kit-cal-sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; padding: 0; }

/* toolbar */
.kit-cal-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin-block-end: 10px; }
.kit-cal-nav { display: flex; gap: 4px; align-items: center; }
.kit-cal-title { flex: 1 1 10rem; min-width: 0; margin: 0; font: 700 1.25rem/1.2 var(--f-ui); color: var(--ink); overflow-wrap: anywhere; }
.kit-cal-btn { min-height: 36px; padding: 6px 12px; font: 600 13px/1.2 var(--f-ui); color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--cal-r); cursor: pointer; }
.kit-cal-btn:hover { background: var(--sunk); }
.kit-cal-btn[aria-disabled="true"] { color: var(--ink-3); cursor: default; background: var(--panel); border-style: dashed; }
.kit-cal-ib { display: inline-grid; place-items: center; width: 36px; padding: 0; }
[dir="rtl"] .kit-cal-chev { transform: scaleX(-1); }
.kit-cal-pri { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.kit-cal-pri:hover { background: var(--accent); filter: brightness(1.08); }
.kit-cal-views { display: inline-flex; padding: 2px; gap: 2px; background: var(--sunk); border: 1px solid var(--rule); border-radius: calc(var(--cal-r) + 2px); }
.kit-cal-vb { min-height: 32px; padding: 4px 12px; font: 600 13px/1.2 var(--f-ui); color: var(--ink-2); background: transparent; border: 1px solid transparent; border-radius: var(--cal-r); cursor: pointer; }
.kit-cal-vb:hover { color: var(--ink); }
.kit-cal-vb[aria-checked="true"] { color: var(--ink); background: var(--panel); border-color: var(--rule); box-shadow: 0 1px 2px color-mix(in srgb, var(--ink) 14%, transparent); }
.kit-cal :is(button, [tabindex]):focus { outline: none; }
.kit-cal :is(button, [tabindex], input):focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 2px; position: relative; z-index: 3; }

/* month */
.kit-cal-month { display: grid; border: 1px solid var(--rule); border-radius: var(--cal-r); overflow: hidden; background: var(--panel); }
.kit-cal-row { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); }
.kit-cal-wn .kit-cal-row { grid-template-columns: 2.25rem repeat(7, minmax(0, 1fr)); }
.kit-cal-head { border-block-end: 1px solid var(--rule); background: var(--sunk); }
.kit-cal-ch { padding: 6px 8px; font: 600 12px/1.2 var(--f-ui); color: var(--ink-2); text-align: start; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kit-cal-strip { grid-template-rows: var(--cal-rows); row-gap: 2px; }
.kit-cal-month .kit-cal-strip + .kit-cal-strip { border-block-start: 1px solid var(--rule-2); }
.kit-cal-month .kit-cal-strip { min-height: 6rem; }
.kit-cal-rh { grid-row: 1 / -1; padding: 6px 4px; font: 500 11px/1.2 var(--f-mono); color: var(--ink-2); text-align: center; background: var(--sunk); border-inline-end: 1px solid var(--rule-2); }
.kit-cal-cell { grid-row: 1 / -1; min-width: 0; padding: 4px 6px; border-inline-start: 1px solid var(--rule-2); cursor: pointer; display: flex; flex-direction: column; gap: 4px; }
.kit-cal-cell:first-child, .kit-cal-rh + .kit-cal-cell { border-inline-start: 0; }
.kit-cal-month .kit-cal-cell:hover { background: color-mix(in srgb, var(--sunk) 55%, var(--panel)); }
.kit-cal-we { background: color-mix(in srgb, var(--sunk) 60%, var(--panel)); }
.kit-cal-out .kit-cal-num { color: var(--ink-3); font-weight: 400; }
.kit-cal-out { background: color-mix(in srgb, var(--bg) 45%, var(--panel)); }
.kit-cal-top-line { display: flex; align-items: center; gap: 6px; min-width: 0; }
.kit-cal-num { display: inline-grid; place-items: center; min-width: 1.6rem; height: 1.6rem; padding: 0 4px; border-radius: 999px; font: 600 13px/1 var(--f-ui); font-variant-numeric: tabular-nums; color: var(--ink); }
.kit-cal-is-today .kit-cal-num { background: var(--accent); color: var(--accent-ink); font-weight: 800; }
.kit-cal-tword { font: 700 11px/1 var(--f-ui); color: var(--accent); text-transform: uppercase; letter-spacing: .04em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kit-cal-cell[aria-disabled="true"], .kit-cal-slot[aria-disabled="true"] { cursor: not-allowed; background-image: repeating-linear-gradient(135deg, transparent 0 6px, color-mix(in srgb, var(--rule) 55%, transparent) 6px 7px); }
.kit-cal-cell[aria-disabled="true"] .kit-cal-num { color: var(--ink-3); text-decoration: line-through; }
.kit-cal-sel, .kit-cal-month .kit-cal-sel:hover { background-color: var(--accent-soft); background-image: repeating-linear-gradient(45deg, transparent 0 5px, color-mix(in srgb, var(--accent) 22%, transparent) 5px 6px); box-shadow: inset 0 0 0 2px var(--accent); }
.kit-cal-dots { display: none; }
.kit-cal-ev { position: relative; z-index: 1; display: flex; align-items: center; gap: 4px; min-width: 0; margin-inline: 3px; padding: 0 6px; height: var(--cal-bar-h);
  font: 500 12px/1 var(--f-ui); color: var(--ink); border-radius: 5px; cursor: pointer; overflow: hidden; white-space: nowrap; }
.kit-cal-bar { background: color-mix(in srgb, var(--ev) 20%, var(--panel)); border-inline-start: 3px solid var(--ev); font-weight: 600; }
.kit-cal-bar:hover { background: color-mix(in srgb, var(--ev) 32%, var(--panel)); }
.kit-cal-chip:hover { background: var(--sunk); }
.kit-cal-chip::before { content: ""; flex: 0 0 auto; width: 8px; height: 8px; border-radius: 999px; background: var(--ev); }
.kit-cal-tm { flex: 0 0 auto; color: var(--ink-2); font-variant-numeric: tabular-nums; unicode-bidi: isolate; }
.kit-cal-tt { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.kit-cal-cs { margin-inline-start: 0; border-start-start-radius: 0; border-end-start-radius: 0; }
.kit-cal-ce { margin-inline-end: 0; border-start-end-radius: 0; border-end-end-radius: 0; }
.kit-cal-bar.kit-cal-cs::before { content: "‹"; color: var(--ink-2); font-weight: 700; }
.kit-cal-bar.kit-cal-ce::after { content: "›"; margin-inline-start: auto; color: var(--ink-2); font-weight: 700; }
.kit-cal-more { z-index: 1; align-self: center; margin-inline: 6px; font: 600 11.5px/1.2 var(--f-ui); color: var(--ink-2); cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-decoration: underline; text-underline-offset: 2px; }
.kit-cal-more:hover { color: var(--ink); }
.kit-cal-under { display: none; }

/* time views */
.kit-cal-scroll { position: relative; max-height: var(--cal-height, 34rem); overflow: auto; border: 1px solid var(--rule); border-radius: var(--cal-r); background: var(--panel); overscroll-behavior: contain; }
.kit-cal-top { position: sticky; top: 0; z-index: 5; background: var(--panel); border-block-end: 1px solid var(--rule); }
.kit-cal-dh, .kit-cal-ad .kit-cal-row, .kit-cal-tg, .kit-cal-trow { grid-template-columns: var(--cal-axis) repeat(var(--cal-days), minmax(0, 1fr)); }
.kit-cal-dh { display: grid; background: var(--sunk); border-block-end: 1px solid var(--rule-2); }
.kit-cal-zone { align-self: end; padding: 4px; font: 500 10.5px/1.2 var(--f-mono); color: var(--ink-2); text-align: center; overflow-wrap: anywhere; }
.kit-cal-dhb { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 2px 6px; min-width: 0; min-height: 44px; padding: 4px; font: 600 12px/1.2 var(--f-ui);
  color: var(--ink-2); background: transparent; border: 0; border-inline-start: 1px solid var(--rule-2); cursor: pointer; }
.kit-cal-dhb:hover { background: var(--panel); color: var(--ink); }
.kit-cal-dhb.kit-cal-we { background: color-mix(in srgb, var(--sunk) 70%, var(--rule-2)); }
.kit-cal-dhb .kit-cal-tword { flex-basis: 100%; text-align: center; }
.kit-cal-ad .kit-cal-row { min-height: 2rem; }
.kit-cal-ad .kit-cal-rh { display: grid; place-items: center; font: 600 10.5px/1.2 var(--f-ui); color: var(--ink-2); background: transparent; border: 0; text-align: center; }
.kit-cal-ad .kit-cal-cell { padding: 0; cursor: cell; }
.kit-cal-tgw { position: relative; }
.kit-cal-tg { display: grid; grid-auto-rows: calc(var(--cal-hour, 3rem) * 24 / var(--cal-slots)); }
.kit-cal-trow { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; }
.kit-cal-trow .kit-cal-rh { position: relative; grid-row: auto; padding: 0; background: transparent; border: 0; }
.kit-cal-ax { position: absolute; inset-inline-end: 6px; top: 0; transform: translateY(-50%); font: 500 11px/1 var(--f-mono); color: var(--ink-2); white-space: nowrap; font-variant-numeric: tabular-nums; }
.kit-cal-slot { border-inline-start: 1px solid var(--rule-2); cursor: cell; }
.kit-cal-hour .kit-cal-slot { border-block-start: 1px solid var(--rule-2); }
.kit-cal-trow:not(.kit-cal-hour) .kit-cal-slot { border-block-start: 1px dotted color-mix(in srgb, var(--rule-2) 70%, transparent); }
.kit-cal-slot.kit-cal-is-today { background: color-mix(in srgb, var(--accent-soft) 35%, transparent); }
.kit-cal-slot:hover { background-color: color-mix(in srgb, var(--sunk) 70%, transparent); }
.kit-cal-evl { position: absolute; inset-block: 0; inset-inline-start: var(--cal-axis); inset-inline-end: 0; display: grid; grid-template-columns: repeat(var(--cal-days), minmax(0, 1fr)); pointer-events: none; }
.kit-cal-col { position: relative; min-width: 0; margin-inline-end: 4px; }
.kit-cal-tev { position: absolute; display: flex; flex-direction: column; align-items: flex-start; gap: 1px; min-width: 0; padding: 3px 6px; overflow: hidden; pointer-events: auto;
  font: 12px/1.25 var(--f-ui); color: var(--ink); text-align: start; cursor: pointer; background: color-mix(in srgb, var(--ev) 22%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--ev) 45%, var(--panel)); border-inline-start: 4px solid var(--ev); border-radius: 6px; box-shadow: 0 0 0 1px var(--panel); }
.kit-cal-tev { container: kit-cal-ev / inline-size; }
.kit-cal-tev:hover { background: color-mix(in srgb, var(--ev) 34%, var(--panel)); z-index: 2; }
.kit-cal-tev .kit-cal-tt { font-weight: 700; max-width: 100%; white-space: nowrap; }
.kit-cal-tev .kit-cal-tm, .kit-cal-loc { max-width: 100%; font-size: 11.5px; color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kit-cal-short { flex-direction: row; align-items: center; gap: 6px; padding-block: 0; }
.kit-cal-short .kit-cal-loc { display: none; }
.kit-cal-short .kit-cal-tt { flex: 0 1 auto; min-width: 2.5em; }
.kit-cal-short .kit-cal-tm { flex: 0 100 auto; min-width: 0; }
.kit-cal-tev.kit-cal-cs { border-start-start-radius: 0; border-start-end-radius: 0; border-block-start-style: dashed; }
.kit-cal-tev.kit-cal-ce { border-end-start-radius: 0; border-end-end-radius: 0; border-block-end-style: dashed; }
.kit-cal-drag { touch-action: none; }
.kit-cal-dragging { z-index: 4; opacity: .85; box-shadow: var(--shadow); cursor: grabbing; }
.kit-cal-rz { position: absolute; inset-inline: 0; bottom: 0; height: 7px; cursor: ns-resize; }
.kit-cal-short .kit-cal-rz::after { display: none; }
.kit-cal-rz::after { content: ""; position: absolute; left: 50%; bottom: 2px; width: 18px; height: 2px; margin-left: -9px; border-radius: 2px; background: color-mix(in srgb, var(--ink) 40%, transparent); }
.kit-cal-now { position: absolute; inset-inline: -4px 0; height: 0; border-block-start: 2px solid var(--danger); z-index: 3; pointer-events: none; }
.kit-cal-now::before { content: ""; position: absolute; inset-inline-start: -5px; top: -6px; width: 10px; height: 10px; border-radius: 999px; background: var(--danger); }

@container kit-cal-ev (max-width: 64px) {
  .kit-cal-tev .kit-cal-tm, .kit-cal-tev .kit-cal-loc { display: none; }
  .kit-cal-tev .kit-cal-tt { white-space: normal; overflow-wrap: anywhere; font-size: 11px; line-height: 1.15; }
}
@container kit-cal-ev (max-width: 40px) {
  .kit-cal-tev .kit-cal-tt { writing-mode: vertical-rl; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-height: 100%; font-size: 11px; line-height: 1.1; }
}

/* agenda and lists */
.kit-cal-agenda { display: grid; gap: 4px; }
.kit-cal-ag-day { display: grid; grid-template-columns: 7.5rem minmax(0, 1fr); gap: 4px 12px; padding: 10px 4px; border-block-start: 1px solid var(--rule-2); }
.kit-cal-ag-day:first-child { border-block-start: 0; }
.kit-cal-ag-h { display: flex; flex-wrap: wrap; align-items: baseline; align-self: start; align-content: start; gap: 2px 8px; margin: 0; font: 600 13px/1.3 var(--f-ui); color: var(--ink-2); }
.kit-cal-ag-n { min-width: 2rem; font: 700 1.35rem/1 var(--f-ui); color: var(--ink); font-variant-numeric: tabular-nums; }
.kit-cal-is-today > .kit-cal-ag-h .kit-cal-ag-n { display: inline-grid; place-items: center; min-width: 2.1rem; height: 2.1rem; border-radius: 999px; background: var(--accent); color: var(--accent-ink); font-size: 1.05rem; }
.kit-cal-ag-w { display: grid; min-width: 0; }
.kit-cal-ag-my { font-weight: 400; font-size: 12px; color: var(--ink-2); }
.kit-cal-badge { padding: 1px 7px; border: 1px solid var(--accent); border-radius: 999px; font: 700 10.5px/1.4 var(--f-ui); color: var(--accent); text-transform: uppercase; letter-spacing: .04em; }
.kit-cal-ag-list, .kit-cal-list { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; min-width: 0; }
.kit-cal-ag-ev, .kit-cal-li { display: grid; grid-template-columns: minmax(5.5rem, max-content) 10px minmax(0, 1fr); align-items: start; gap: 4px 10px; width: 100%; min-height: 40px; padding: 8px 10px;
  font: 14px/1.35 var(--f-ui); color: var(--ink); text-align: start; background: var(--panel); border: 1px solid var(--rule-2); border-radius: var(--cal-r); cursor: pointer; }
.kit-cal-ag-ev:hover, .kit-cal-li:hover { border-color: var(--rule); background: var(--sunk); }
.kit-cal-ag-tm { color: var(--ink-2); font-size: 13px; font-variant-numeric: tabular-nums; unicode-bidi: isolate; }
.kit-cal-sw { width: 10px; height: 1.1em; margin-block-start: .15em; border-radius: 3px; background: var(--ev, var(--accent)); }
.kit-cal-ag-main { display: grid; gap: 2px; min-width: 0; }
.kit-cal-ag-main .kit-cal-tt { font-weight: 650; overflow-wrap: anywhere; }
.kit-cal-ag-meta { font-size: 12.5px; color: var(--ink-2); overflow-wrap: anywhere; }
.kit-cal-empty { margin: 0; padding: 18px 8px; color: var(--ink-2); text-align: center; border: 1px dashed var(--rule); border-radius: var(--cal-r); }
.kit-cal-ag-day .kit-cal-empty { padding: 8px; text-align: start; }

/* the dialog */
.kit-cal-pop { position: absolute; z-index: 20; width: min(22rem, calc(100% - 16px)); max-height: 70vh; overflow: auto; padding: 12px 14px 14px; background: var(--panel); color: var(--ink);
  border: 1px solid var(--rule); border-radius: calc(var(--cal-r) + 4px); box-shadow: var(--shadow); }
.kit-cal-pop[hidden] { display: none; }
.kit-cal-ph { display: flex; align-items: flex-start; gap: 10px; }
.kit-cal-ph .kit-cal-sw { flex: 0 0 auto; width: 12px; height: 12px; margin-block-start: .35em; }
.kit-cal-pt { flex: 1 1 auto; min-width: 0; margin: 0; font: 700 1rem/1.35 var(--f-ui); overflow-wrap: anywhere; }
.kit-cal-x { flex: 0 0 auto; display: grid; place-items: center; width: 32px; height: 32px; margin: -4px -6px 0 0; padding: 0; color: var(--ink-2); background: transparent; border: 1px solid transparent; border-radius: var(--cal-r); cursor: pointer; }
.kit-cal-x:hover { background: var(--sunk); color: var(--ink); }
.kit-cal-when { margin: 6px 0 0; font: 600 13.5px/1.4 var(--f-ui); color: var(--ink-2); font-variant-numeric: tabular-nums; }
.kit-cal-dl { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 4px 12px; margin: 10px 0 0; font-size: 13.5px; }
.kit-cal-dl dt { font-weight: 600; color: var(--ink-2); }
.kit-cal-dl dd { margin: 0; overflow-wrap: anywhere; }
.kit-cal-desc { white-space: pre-line; }
.kit-cal-pop .kit-cal-list { margin-block-start: 10px; }
.kit-cal-li { grid-template-columns: 10px minmax(4.5rem, max-content) minmax(0, 1fr); padding: 6px 8px; min-height: 36px; font-size: 13.5px; }
.kit-cal-li .kit-cal-tt { white-space: normal; overflow-wrap: anywhere; }
.kit-cal-link { margin-block-start: 10px; padding: 6px 0; font: 600 13px/1.2 var(--f-ui); color: var(--accent); background: none; border: 0; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.kit-cal-edit { margin-block-start: 6px; border-block-start: 1px solid var(--rule-2); }
.kit-cal-form { display: grid; gap: 8px; margin-block-start: 4px; }
.kit-cal-form[hidden] { display: none; }
.kit-cal-fs { display: flex; flex-wrap: wrap; gap: 6px 10px; margin: 0; padding: 0; border: 0; min-width: 0; }
.kit-cal-fs legend { padding: 0; margin-block-end: 2px; font: 600 12px/1.2 var(--f-ui); color: var(--ink-2); }
.kit-cal-fl { display: grid; gap: 2px; font-size: 12px; color: var(--ink-2); }
.kit-cal-in { min-height: 36px; padding: 4px 8px; font: 14px var(--f-ui); color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--cal-r); }
.kit-cal-in:disabled { color: var(--ink-3); background: var(--sunk); }
.kit-cal-in[aria-invalid="true"] { border-color: var(--danger); box-shadow: inset 0 0 0 1px var(--danger); }
.kit-cal-err { margin: 0; font-size: 13px; font-weight: 600; color: var(--danger); }
.kit-cal-err:empty { display: none; }
.kit-cal-err:not(:empty)::before { content: "! "; }
.kit-cal-acts { display: flex; justify-content: flex-end; gap: 8px; }

/* narrow: month shows dots and the chosen day's list; the time view shows fewer days (set by the script) */
@container kit-cal (max-width: 479.98px) {
  .kit-cal-title { flex-basis: 100%; order: -1; font-size: 1.1rem; }
  .kit-cal-views { flex: 1 1 auto; }
  .kit-cal-vb { flex: 1 1 0; padding-inline: 6px; }
  .kit-cal-month .kit-cal-strip { grid-template-rows: auto; min-height: 0; padding: 0; }
  .kit-cal-month .kit-cal-ev, .kit-cal-month .kit-cal-more, .kit-cal-tword { display: none; }
  .kit-cal-month .kit-cal-cell { min-height: 48px; padding: 4px 2px; align-items: center; gap: 2px; }
  .kit-cal-ch { padding: 6px 2px; text-align: center; }
  .kit-cal-dots { display: flex; align-items: center; justify-content: center; gap: 2px; min-height: 8px; }
  .kit-cal-pip { width: 6px; height: 6px; border-radius: 999px; background: var(--ev); box-shadow: 0 0 0 1px var(--panel); }
  .kit-cal-pipn { font: 600 9px/1 var(--f-ui); color: var(--ink-2); }
  .kit-cal-month .kit-cal-cell[tabindex="0"] { box-shadow: inset 0 0 0 2px var(--ink-3); }
  .kit-cal-under { display: block; margin-block-start: 10px; }
  .kit-cal-wn .kit-cal-row { grid-template-columns: 1.75rem repeat(7, minmax(0, 1fr)); }
  .kit-cal-ag-day { grid-template-columns: minmax(0, 1fr); }
  .kit-cal-ag-ev { grid-template-columns: 10px minmax(0, 1fr); }
  .kit-cal-ag-ev .kit-cal-ag-tm { grid-row: 1; grid-column: 2; }
  .kit-cal-ag-ev .kit-cal-ag-main { grid-row: 2; grid-column: 2; }
  .kit-cal-ag-ev .kit-cal-sw { grid-row: 1 / span 2; grid-column: 1; }
  .kit-cal { --cal-axis: 3rem; }
}
@media (pointer: coarse) {
  .kit-cal-btn, .kit-cal-vb, .kit-cal-ib, .kit-cal-x { min-height: 44px; min-width: 44px; }
  .kit-cal-ag-ev, .kit-cal-li { min-height: 44px; }
  .kit-cal-month .kit-cal-cell { min-height: 44px; }
}
